/**
 * Goes through the whole feed replication workflow checking its instances status while.
 * submitting feed, scheduling it, performing different combinations of actions like
 * -submit, -resume, -kill, -rerun.
 */
@Test(groups = { "multiCluster" })
public void feedInstanceStatusRunning() throws Exception {
    bundles[0].setInputFeedDataPath(feedInputPath);
    AssertUtil.assertSucceeded(prism.getClusterHelper().submitEntity(bundles[0].getClusters().get(0)));
    AssertUtil.assertSucceeded(prism.getClusterHelper().submitEntity(bundles[1].getClusters().get(0)));
    AssertUtil.assertSucceeded(prism.getClusterHelper().submitEntity(bundles[2].getClusters().get(0)));
    String feed = bundles[0].getDataSets().get(0);
    String feedName = Util.readEntityName(feed);
    feed = FeedMerlin.fromString(feed).clearFeedClusters().toString();
    String startTime = TimeUtil.getTimeWrtSystemTime(-50);
    final String startPlus20Min = TimeUtil.addMinsToTime(startTime, 20);
    final String startPlus40Min = TimeUtil.addMinsToTime(startTime, 40);
    final String startPlus100Min = TimeUtil.addMinsToTime(startTime, 100);
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[1].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startTime, TimeUtil.addMinsToTime(startTime, 65)).withClusterType(ClusterType.SOURCE).withPartition("US/${cluster.colo}").build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[0].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startPlus20Min, TimeUtil.addMinsToTime(startTime, 85)).withClusterType(ClusterType.TARGET).build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[2].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startPlus40Min, TimeUtil.addMinsToTime(startTime, 110)).withClusterType(ClusterType.SOURCE).withPartition("UK/${cluster.colo}").build()).toString();
    LOGGER.info("feed: " + Util.prettyPrintXml(feed));
    //status before submit
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus100Min + "&end=" + TimeUtil.addMinsToTime(startTime, 120));
    AssertUtil.assertSucceeded(prism.getFeedHelper().submitEntity(feed));
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + startPlus100Min);
    AssertUtil.assertSucceeded(prism.getFeedHelper().schedule(feed));
    // both replication instances
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + startPlus100Min);
    // single instance at -30
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus20Min);
    //single at -10
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    //single at 10
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    //single at 30
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    String postFix = "/US/" + cluster2.getClusterHelper().getColoName();
    String prefix = bundles[0].getFeedDataPathPrefix();
    HadoopUtil.deleteDirIfExists(prefix.substring(1), cluster2FS);
    HadoopUtil.lateDataReplenish(cluster2FS, 80, 20, prefix, postFix);
    postFix = "/UK/" + cluster3.getClusterHelper().getColoName();
    prefix = bundles[0].getFeedDataPathPrefix();
    HadoopUtil.deleteDirIfExists(prefix.substring(1), cluster3FS);
    HadoopUtil.lateDataReplenish(cluster3FS, 80, 20, prefix, postFix);
    // both replication instances
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + startPlus100Min);
    // single instance at -30
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus20Min);
    //single at -10
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    //single at 10
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    //single at 30
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus40Min);
    LOGGER.info("Wait till feed goes into running ");
    //suspend instances -10
    prism.getFeedHelper().getProcessInstanceSuspend(feedName, "?start=" + startPlus40Min);
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus20Min + "&end=" + startPlus40Min);
    //resuspend -10 and suspend -30 source specific
    prism.getFeedHelper().getProcessInstanceSuspend(feedName, "?start=" + startPlus20Min + "&end=" + startPlus40Min);
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus20Min + "&end=" + startPlus40Min);
    //resume -10 and -30
    prism.getFeedHelper().getProcessInstanceResume(feedName, "?start=" + startPlus20Min + "&end=" + startPlus40Min);
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startPlus20Min + "&end=" + startPlus40Min);
    //get running instances
    prism.getFeedHelper().getRunningInstance(feedName);
    //rerun succeeded instance
    prism.getFeedHelper().getProcessInstanceRerun(feedName, "?start=" + startTime);
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + startPlus20Min);
    //kill instance
    prism.getFeedHelper().getProcessInstanceKill(feedName, "?start=" + TimeUtil.addMinsToTime(startTime, 44));
    prism.getFeedHelper().getProcessInstanceKill(feedName, "?start=" + startTime);
    //end time should be less than end of validity i.e startTime + 110
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + TimeUtil.addMinsToTime(startTime, 110));
    //rerun killed instance
    prism.getFeedHelper().getProcessInstanceRerun(feedName, "?start=" + startTime);
    prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + TimeUtil.addMinsToTime(startTime, 110));
    //kill feed
    prism.getFeedHelper().delete(feed);
    InstancesResult responseInstance = prism.getFeedHelper().getProcessInstanceStatus(feedName, "?start=" + startTime + "&end=" + TimeUtil.addMinsToTime(startTime, 110));
    LOGGER.info(responseInstance.getMessage());
}

