    // use the start date for both as this will only generate 2 partitions.
    List<String> dataDates = TimeUtil.getMinuteDatesOnEitherSide(startDate, dataEndDate, 60, DateTimeFormat.forPattern(datePattern));
    final List<String> dataset = HadoopUtil.flattenAndPutDataInFolder(clusterFS, localHCatData, testHdfsDir, dataDates);
    final String col1Name = "id";
    final String col2Name = "value";
    final String partitionColumn = "dt";
    ArrayList<HCatFieldSchema> cols = new ArrayList<>();
    cols.add(HCatUtil.getStringSchema(col1Name, col1Name + " comment"));
    cols.add(HCatUtil.getStringSchema(col2Name, col2Name + " comment"));
    ArrayList<HCatFieldSchema> partitionCols = new ArrayList<>();
    // create table on cluster 1 and add data to it.
    partitionCols.add(HCatUtil.getStringSchema(partitionColumn, partitionColumn + " partition"));
    createTable(clusterHC, dbName, tblName, cols, partitionCols, testHdfsDir);
    addPartitionsToTable(dataDates, dataset, "dt", dbName, tblName, clusterHC);
    // create table on target cluster.
    createTable(cluster2HC, dbName, tblName, cols, partitionCols, testHdfsDir);
    createTable(cluster3HC, dbName, tblName, cols, partitionCols, testHdfsDir);
    Bundle.submitCluster(bundles[0], bundles[1], bundles[2]);
    bundles[0].setInputFeedPeriodicity(1, Frequency.TimeUnit.hours);
    bundles[0].setInputFeedValidity(startDate, endDate);
    bundles[0].setInputFeedTableUri(tableUri);
    String feed = bundles[0].getDataSets().get(0);
    // set the cluster 2 as the target.
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[1].getClusters().get(0))).withRetention("months(9000)", ActionType.DELETE).withValidity(startDate, endDate).withClusterType(ClusterType.TARGET).withTableUri(tableUri).build()).toString();
    // set the cluster 3 as the target.
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[2].getClusters().get(0))).withRetention("months(9000)", ActionType.DELETE).withValidity(startDate, endDate).withClusterType(ClusterType.TARGET).withTableUri(tableUri).build()).toString();
    AssertUtil.assertSucceeded(prism.getFeedHelper().submitAndSchedule(feed));
    TimeUtil.sleepSeconds(TIMEOUT);
    //check if all coordinators exist
    Assert.assertEquals(OozieUtil.checkIfFeedCoordExist(cluster2OC, Util.readEntityName(feed), "REPLICATION"), 1);
    //check if all coordinators exist
    Assert.assertEquals(OozieUtil.checkIfFeedCoordExist(cluster3OC, Util.readEntityName(feed), "REPLICATION"), 1);
    //replication should start, wait while it ends
    // we will check for 2 instances so that both partitions are copied over.
    InstanceUtil.waitTillInstanceReachState(cluster2OC, Util.readEntityName(feed), 2, CoordinatorAction.Status.SUCCEEDED, EntityType.FEED, 30);
    //replication should start, wait while it ends
    // we will check for 2 instances so that both partitions are copied over.
    InstanceUtil.waitTillInstanceReachState(cluster3OC, Util.readEntityName(feed), 2, CoordinatorAction.Status.SUCCEEDED, EntityType.FEED);
    //check if data was replicated correctly
    List<Path> srcData = HadoopUtil.getAllFilesRecursivelyHDFS(clusterFS, new Path(testHdfsDir));
    LOGGER.info("Data on source cluster: " + srcData);
    List<Path> cluster2TargetData = HadoopUtil.getAllFilesRecursivelyHDFS(cluster2FS, new Path(testHdfsDir));
    LOGGER.info("Data on target cluster: " + cluster2TargetData);
    AssertUtil.checkForListSizes(srcData, cluster2TargetData);
    List<Path> cluster3TargetData = HadoopUtil.getAllFilesRecursivelyHDFS(cluster3FS, new Path(testHdfsDir));
    LOGGER.info("Data on target cluster: " + cluster3TargetData);
    AssertUtil.checkForListSizes(srcData, cluster3TargetData);
}

@Test(enabled = true, dataProvider = "loopBelow", timeOut = 900000, groups = "embedded")
public void testHCatRetention(int retentionPeriod, RetentionUnit retentionUnit, FreqType freqType) throws Exception {
    /*the hcatalog table that is created changes tablename characters to lowercase. So the
          name in the feed should be the same.*/
    tableName = String.format("testhcatretention_%s_%d", retentionUnit.getValue(), retentionPeriod);
    createPartitionedTable(cli, dBName, tableName, baseTestHDFSDir, freqType);
    FeedMerlin feedElement = new FeedMerlin(bundle.getInputFeedFromBundle());
    feedElement.setTableValue(dBName, tableName, freqType.getHcatPathValue());
    feedElement.setRetentionValue(retentionUnit.getValue() + "(" + retentionPeriod + ")");
    if (retentionPeriod <= 0) {
        AssertUtil.assertFailed(prism.getFeedHelper().submitEntity(bundle.getInputFeedFromBundle()));
    } else {
        final DateTime dataStartTime = new DateTime(feedElement.getClusters().getClusters().get(0).getValidity().getStart(), DateTimeZone.UTC).withSecondOfMinute(0);
        final DateTime dataEndTime = new DateTime(feedElement.getClusters().getClusters().get(0).getValidity().getEnd(), DateTimeZone.UTC).withSecondOfMinute(0);
        final List<DateTime> dataDates = TimeUtil.getDatesOnEitherSide(dataStartTime, dataEndTime, freqType);
        final List<String> dataDateStrings = TimeUtil.convertDatesToString(dataDates, freqType.getFormatter());
        AssertUtil.checkForListSizes(dataDates, dataDateStrings);
        final List<String> dataFolders = HadoopUtil.flattenAndPutDataInFolder(clusterFS, OSUtil.SINGLE_FILE, baseTestHDFSDir, dataDateStrings);
        addPartitionsToExternalTable(cli, dBName, tableName, freqType, dataDates, dataFolders);
        List<String> initialData = getHadoopDataFromDir(clusterFS, baseTestHDFSDir, testDir, freqType);
        List<HCatPartition> initialPtnList = cli.getPartitions(dBName, tableName);
        AssertUtil.checkForListSizes(initialData, initialPtnList);
        AssertUtil.assertSucceeded(prism.getFeedHelper().submitAndSchedule(feedElement.toString()));
        final String bundleId = OozieUtil.getBundles(clusterOC, feedElement.getName(), EntityType.FEED).get(0);
        OozieUtil.waitForRetentionWorkflowToSucceed(bundleId, clusterOC);
        AssertUtil.assertSucceeded(prism.getFeedHelper().suspend(feedElement.toString()));
        List<String> expectedOutput = getExpectedOutput(retentionPeriod, retentionUnit, freqType, new DateTime(DateTimeZone.UTC), initialData);
        List<String> finalData = getHadoopDataFromDir(clusterFS, baseTestHDFSDir, testDir, freqType);
        List<HCatPartition> finalPtnList = cli.getPartitions(dBName, tableName);
        LOGGER.info("checking expectedOutput and finalPtnList");
        AssertUtil.checkForListSizes(expectedOutput, finalPtnList);
        LOGGER.info("checking expectedOutput and finalData");
        AssertUtil.checkForListSizes(expectedOutput, finalData);
        LOGGER.info("finalData = " + finalData);
        LOGGER.info("expectedOutput = " + expectedOutput);
        Assert.assertTrue(Arrays.deepEquals(finalData.toArray(new String[finalData.size()]), expectedOutput.toArray(new String[expectedOutput.size()])), "expectedOutput and finalData don't match");
    }
}

