        }
        Assert.assertTrue(validateFailureRetries(clusterOC, bundleId, 1), "Failure Retry validation failed");
        retry.setAttempts((retry.getAttempts() - 2));
        bundles[0].setRetry(retry);
        LOGGER.info("going to update process at:" + DateTime.now(DateTimeZone.UTC));
        if ((retry.getAttempts() - 2) > 0) {
            Assert.assertTrue(prism.getProcessHelper().update((bundles[0].getProcessData()), bundles[0].getProcessData()).getMessage().contains("updated successfully"), "process was not updated successfully");
            String newBundleId = OozieUtil.getLatestBundleID(clusterOC, bundles[0].getProcessName(), EntityType.PROCESS);
            Assert.assertEquals(bundleId, newBundleId, "its creating a new bundle!!!");
            //now to validate all failed instances to check if they were retried or not.
            validateRetry(clusterOC, bundleId, retry.getAttempts() - 2);
