 * ua1/ua2
 * ua1/ua2
 * <p/>
 * ua2 has following part data
 * ua1/ua3
 * ua1/ua3
 * ua1/ua3
 * <p/>
 * ua1 is the target, which in the end should have all ua1 data
 * after first instance succeed data in put into relevant source and late should rerun
 * after first late succeed data is put into other source and late should not rerun
 */
@Test(groups = { "multiCluster" })
public void mixedTest02() throws Exception {
    bundles[0].setInputFeedDataPath(inputPath);
    Bundle.submitCluster(bundles[0], bundles[1], bundles[2]);
    //set availability flag as _success
    bundles[0].setInputFeedAvailabilityFlag("_SUCCESS");
    //get feed
    String feed = bundles[0].getDataSets().get(0);
    feed = FeedMerlin.fromString(feed).clearFeedClusters().toString();
    String startTime = TimeUtil.getTimeWrtSystemTime(3);
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[1].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startTime, "2099-01-01T00:00Z").withClusterType(ClusterType.SOURCE).withPartition("ua1/${cluster.colo}").build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[0].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startTime, "2099-01-01T00:00Z").withClusterType(ClusterType.TARGET).build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[2].getClusters().get(0))).withRetention("hours(10)", ActionType.DELETE).withValidity(startTime, "2099-01-01T00:00Z").withClusterType(ClusterType.SOURCE).withPartition("ua1/${cluster.colo}").build()).toString();
    //create data in colos
    String postFix = "/ua1/ua2";
    String prefix = bundles[0].getFeedDataPathPrefix();
    HadoopUtil.deleteDirIfExists(prefix.substring(1), cluster2FS);
    HadoopUtil.lateDataReplenishWithoutSuccess(cluster2FS, 90, 1, prefix, postFix);
    postFix = "/ua2/ua2";
    HadoopUtil.lateDataReplenishWithoutSuccess(cluster2FS, 90, 1, prefix, postFix);
    postFix = "/ua3/ua2";
    HadoopUtil.lateDataReplenishWithoutSuccess(cluster2FS, 90, 1, prefix, postFix);
    //put _SUCCESS in parent folder UA2
    HadoopUtil.putFileInFolderHDFS(cluster2FS, 90, 1, prefix, "_SUCCESS");
    postFix = "/ua1/ua3";
    HadoopUtil.deleteDirIfExists(prefix.substring(1), cluster3FS);
    HadoopUtil.lateDataReplenish(cluster3FS, 90, 1, prefix, postFix);
    postFix = "/ua2/ua3";
    HadoopUtil.lateDataReplenish(cluster3FS, 90, 1, prefix, postFix);
    postFix = "/ua3/ua3";
    HadoopUtil.lateDataReplenish(cluster3FS, 90, 1, prefix, postFix);
    //put _SUCCESS in parent folder of UA3
    HadoopUtil.putFileInFolderHDFS(cluster3FS, 90, 1, prefix, "_SUCCESS");
    TimeUtil.sleepSeconds(15);
    //submit and schedule feed
    LOGGER.info("feed: " + Util.prettyPrintXml(feed));
    prism.getFeedHelper().submitAndSchedule(feed);
    TimeUtil.sleepSeconds(10);
    //wait till 1st instance of replication coord is SUCCEEDED
    String bundleId = OozieUtil.getLatestBundleID(cluster1OC, Util.readEntityName(feed), EntityType.FEED);
    List<String> replicationCoordIDTarget = OozieUtil.getReplicationCoordID(bundleId, cluster1.getFeedHelper());
    for (int i = 0; i < 30; i++) {
        if (InstanceUtil.getInstanceStatusFromCoord(cluster1OC, replicationCoordIDTarget.get(0), 0) == WorkflowJob.Status.SUCCEEDED && InstanceUtil.getInstanceStatusFromCoord(cluster1OC, replicationCoordIDTarget.get(1), 0) == WorkflowJob.Status.SUCCEEDED) {
            break;
        }
        LOGGER.info("still in for loop");
        TimeUtil.sleepSeconds(20);
    }
    Assert.assertEquals(InstanceUtil.getInstanceStatusFromCoord(cluster1OC, replicationCoordIDTarget.get(0), 0), WorkflowJob.Status.SUCCEEDED, "Replication job did not succeed");
    Assert.assertEquals(InstanceUtil.getInstanceStatusFromCoord(cluster1OC, replicationCoordIDTarget.get(1), 0), WorkflowJob.Status.SUCCEEDED, "Replication job did not succeed");
    TimeUtil.sleepSeconds(15);
    /* check for exact folders to be created in ua1 :  ua1/ua2 and ua1/ua3 no other should
           be present. both of
           them should have _success */
    List<String> inputFolderListForColo1 = InstanceUtil.getInputFoldersForInstanceForReplication(cluster1OC, replicationCoordIDTarget.get(0), 1);
    List<String> inputFolderListForColo2 = InstanceUtil.getInputFoldersForInstanceForReplication(cluster1OC, replicationCoordIDTarget.get(1), 1);
    String outPutLocation = InstanceUtil.getOutputFolderForInstanceForReplication(cluster1OC, replicationCoordIDTarget.get(0), 0);
    String outPutBaseLocation = InstanceUtil.getOutputFolderBaseForInstanceForReplication(cluster1OC, replicationCoordIDTarget.get(0), 0);
    List<String> subfolders = HadoopUtil.getHDFSSubFoldersName(cluster1FS, outPutBaseLocation);
    Assert.assertEquals(subfolders.size(), 1);
    Assert.assertEquals(subfolders.get(0), "ua1");
    Assert.assertFalse(HadoopUtil.isFilePresentHDFS(cluster1FS, outPutBaseLocation, "_SUCCESS"));
    Assert.assertTrue(HadoopUtil.isFilePresentHDFS(cluster1FS, outPutLocation, "_SUCCESS"));
    HadoopUtil.flattenAndPutDataInFolder(cluster2FS, OSUtil.NORMAL_INPUT, inputFolderListForColo1);
    HadoopUtil.flattenAndPutDataInFolder(cluster3FS, OSUtil.NORMAL_INPUT, inputFolderListForColo2);
    //sleep till late starts
    TimeUtil.sleepTill(TimeUtil.addMinsToTime(startTime, 4));
    //check for run id to  be 1
    Assert.assertTrue(InstanceUtil.getInstanceRunIdFromCoord(cluster1OC, replicationCoordIDTarget.get(0), 0) == 1 && InstanceUtil.getInstanceRunIdFromCoord(cluster1OC, replicationCoordIDTarget.get(1), 0) == 1, "id have to be equal 1");
}

