 */
@Test
public void dependentProcessSucceeded() throws Exception {
    bundles[0].setProcessValidity("2014-06-01T04:00Z", "2014-06-01T04:02Z");
    bundles[0].submitAndScheduleAllFeeds();
    bundles[0].submitAndScheduleProcess();
    InstanceUtil.waitTillInstancesAreCreated(cluster1OC, bundles[0].getProcessData(), 0);
    OozieUtil.createMissingDependencies(cluster1, EntityType.PROCESS, bundles[0].getProcessName(), 0, 0);
    OozieUtil.waitForBundleToReachState(cluster1OC, bundles[0].getProcessName(), Job.Status.SUCCEEDED, 20);
    FeedMerlin feed = new FeedMerlin(bundles[0].getDataSets().get(0)).withProperty("someProp", "someVal");
    AssertUtil.assertSucceeded(prism.getFeedHelper().update(feed.toString(), feed.toString()));
    //check for new feed bundle creation
    Assert.assertEquals(OozieUtil.getNumberOfBundle(cluster1OC, EntityType.FEED, feed.getName()), 2);
    Assert.assertEquals(OozieUtil.getNumberOfBundle(cluster1OC, EntityType.PROCESS, bundles[0].getProcessName()), 1);
}

