 * Check that process was scheduled with new bundle associated to it.
 *
 * @throws Exception
 */
@Test(groups = { "prism", "0.2", "embedded" }, enabled = true, timeOut = 1800000)
public void testRescheduleKilledProcess() throws Exception {
    bundles[0].setProcessValidity(TimeUtil.getTimeWrtSystemTime(-1), TimeUtil.getTimeWrtSystemTime(1));
    HadoopFileEditor hadoopFileEditor = null;
    String process = bundles[0].getProcessData();
    try {
        hadoopFileEditor = new HadoopFileEditor(cluster1.getClusterHelper().getHadoopFS());
        hadoopFileEditor.edit(new ProcessMerlin(process).getWorkflow().getPath() + "/workflow.xml", "<value>${outputData}</value>", "<property>\n" + "                    <name>randomProp</name>\n" + "                    <value>randomValue</value>\n" + "                </property>");
        bundles[0].submitFeedsScheduleProcess(prism);
        InstanceUtil.waitTillInstancesAreCreated(cluster1OC, bundles[0].getProcessData(), 0);
        OozieUtil.createMissingDependencies(cluster1, EntityType.PROCESS, bundles[0].getProcessName(), 0);
        InstanceUtil.waitTillInstanceReachState(cluster1OC, bundles[0].getProcessName(), 2, CoordinatorAction.Status.RUNNING, EntityType.PROCESS, 5);
        OozieUtil.waitForBundleToReachState(cluster1OC, Util.readEntityName(process), Job.Status.KILLED);
        String oldBundleID = OozieUtil.getLatestBundleID(cluster1OC, Util.readEntityName(process), EntityType.PROCESS);
        prism.getProcessHelper().delete(process);
        bundles[0].submitAndScheduleProcess();
        OozieUtil.verifyNewBundleCreation(cluster1OC, oldBundleID, new ArrayList<String>(), process, true, false);
    } finally {
        if (hadoopFileEditor != null) {
            hadoopFileEditor.restore();
        }
    }
}

