@Test
public void testActionsPauseResume() throws URISyntaxException, AuthenticationException, InterruptedException, IOException {
    Assert.assertEquals(searchPage.doSearch(twoProcessesNameStart).size(), 2, "Two results should be present after deletion");
    //select first process
    searchPage.selectRow(1);
    searchPage.clickButton(Button.Schedule);
    List<SearchPage.SearchResult> results = searchPage.getSearchResults();
    String firstProcess = processesMap.get(results.get(0).getEntityName());
    String secondProcess = processesMap.get(results.get(1).getEntityName());
    Assert.assertEquals(results.get(0).getStatus(), EntityStatus.RUNNING, "Unexpected status after 'Schedule' was clicked");
    Assert.assertTrue(prism.getProcessHelper().getStatus(firstProcess).getMessage().contains("RUNNING"), "First process should be RUNNING via API");
    //select two processes
    searchPage.clickSelectAll();
    Assert.assertEquals(searchPage.getButtons(true), EnumSet.of(Button.Delete), "Only 'Delete' should be available for processes with different  statuses");
    searchPage.deselectRow(1);
    searchPage.clickButton(Button.Schedule);
    Assert.assertEquals(searchPage.getSearchResults().get(1).getStatus(), EntityStatus.RUNNING, "Unexpected status after 'Schedule' was clicked");
    Assert.assertTrue(prism.getProcessHelper().getStatus(secondProcess).getMessage().contains("RUNNING"), "Second process should be RUNNING via API");
    searchPage.selectRow(1);
    searchPage.selectRow(2);
    searchPage.clickButton(Button.Suspend);
    Assert.assertEquals(searchPage.getSearchResults().get(0).getStatus(), EntityStatus.SUSPENDED, "Unexpected status after 'Suspend' was clicked");
    Assert.assertTrue(prism.getProcessHelper().getStatus(firstProcess).getMessage().contains("SUSPENDED"), "First process should be SUSPENDED via API");
    Assert.assertEquals(searchPage.getSearchResults().get(1).getStatus(), EntityStatus.SUSPENDED, "Unexpected status after 'Suspend' was clicked");
    Assert.assertTrue(prism.getProcessHelper().getStatus(secondProcess).getMessage().contains("SUSPENDED"), "Second process should be SUSPENDED via API");
    searchPage.clickSelectAll();
    Assert.assertEquals(searchPage.getButtons(true), EnumSet.of(Button.Resume, Button.Delete), "List of active buttons is not correct after selecting two SUSPENDED processes");
}

