        List<Vertex> outVertices = lineageHelper.getVerticesByDirection(piVertex.getId(), Direction.outgoingVertices).filterByType(Vertex.VERTEX_TYPE.FEED_INSTANCE);
        for (Vertex inVertex : inVertices) {
