/**
 * Test checks that UI show expected statuses of submitted Process (SUBMITTED and RUNNING)
 * then checks instances icons to be relevant to statuses of oozie actions
 * and checks that Lineage links are available only for SUCCEEDED instances.
 */
@Test
public void testProcessUI() throws URISyntaxException, IOException, AuthenticationException, JAXBException, OozieClientException, InterruptedException {
    //check Process statuses via UI
    EntitiesPage page = new EntitiesPage(getDriver(), cluster, EntityType.PROCESS);
    page.navigateTo();
    String process = bundles[0].getProcessData();
    String processName = Util.readEntityName(process);
    softAssert.assertEquals(page.getEntityStatus(processName), Page.EntityStatus.SUBMITTED, "Process status should be SUBMITTED");
    prism.getProcessHelper().schedule(process);
    InstanceUtil.waitTillInstanceReachState(clusterOC, processName, 1, CoordinatorAction.Status.RUNNING, EntityType.PROCESS);
    softAssert.assertEquals(page.getEntityStatus(processName), Page.EntityStatus.RUNNING, "Process status should be RUNNING");
    ProcessPage processPage = new ProcessPage(getDriver(), cluster, processName);
    processPage.navigateTo();
    String bundleID = OozieUtil.getLatestBundleID(clusterOC, processName, EntityType.PROCESS);
    Map<Date, CoordinatorAction.Status> actions = OozieUtil.getActionsNominalTimeAndStatus(clusterOC, bundleID, EntityType.PROCESS);
    checkActions(actions, processPage);
    InstanceUtil.waitTillInstanceReachState(clusterOC, processName, 1, CoordinatorAction.Status.SUCCEEDED, EntityType.PROCESS);
    processPage.refresh();
    actions = OozieUtil.getActionsNominalTimeAndStatus(clusterOC, bundleID, EntityType.PROCESS);
    checkActions(actions, processPage);
    softAssert.assertAll();
}

