    // delete
    System.out.println("extension -delete -jobName " + JOB_NAME_1);
    Assert.assertEquals(TestContext.executeWithURL("extension -delete -jobName " + JOB_NAME_1), 0);
    // update
    filePath = TestContext.overlayParametersOverTemplate(TestContext.getTempFile("property", "txt"), HDFS_MIRRORING_PROPERTY_TEMPLATE, getHDFSMirroringProperty(JOB_NAME_2, START_TIME_2, endTime));
