    Assert.assertEquals(TestContext.executeWithURL("extension -validate -extensionName hdfs-mirroring -file " + filePath), 0);
    // failure case: no file input
    System.out.println("extension -submitAndSchedule -extensionName hdfs-mirroring");
    Assert.assertEquals(TestContext.executeWithURL("extension -submitAndSchedule -extensionName hdfs-mirroring"), -1);
    // enumerate
